using System;
namespace Frociart {
    // Metadata shared by native source actions. Generated programs are never executed by the app.
    internal sealed class FlowSourceTarget {
        internal static readonly FlowSourceTarget Python=new FlowSourceTarget("python","Python","py","PythonRuntime.py","Salva il programma completo ed eseguilo con Python 3 sul computer.");
        internal static readonly FlowSourceTarget Java=new FlowSourceTarget("java","Java","java","JavaRuntime.txt","Salva Programma.java, compila con javac ed esegui con java Programma (Java 8+).");
        internal static readonly FlowSourceTarget Kotlin=new FlowSourceTarget("kotlin","Kotlin","kt","KotlinRuntime.kt","Salva Programma.kt. Compila con Kotlin/JVM 1.9+: kotlinc Programma.kt -include-runtime -d Programma.jar. Esegui: java -jar Programma.jar (Java 8+). Il file contiene il programma completo; i disegni si aprono in una finestra. File e bozze usano la cartella di esecuzione.");
        internal static readonly FlowSourceTarget CSharp=new FlowSourceTarget("csharp","C#","cs","CSharpRuntime.txt","Salva Programma.cs. Su Windows: csc /r:System.Numerics.dll Programma.cs. I disegni vengono salvati in SVG.");
        internal static readonly FlowSourceTarget JavaScript=new FlowSourceTarget("javascript","JavaScript","cjs","JavaScriptRuntime.cjs","Salva Programma.cjs ed esegui con node Programma.cjs (Node.js 22+). I disegni vengono salvati in SVG.");
        internal static readonly FlowSourceTarget TypeScript=new FlowSourceTarget("typescript","TypeScript","cts","TypeScriptRuntime.cts","Salva Programma.cts. Compila: tsc --strict --target ES2020 --module node16 Programma.cts. Esegui: node Programma.cjs (Node.js 22+).");
        internal static readonly FlowSourceTarget Cpp=new FlowSourceTarget("cpp","C++","cpp","CppRuntime.txt","Salva Programma.cpp. Compila con g++ -std=c++17 -O2 Programma.cpp -o Programma; avvia Programma. Su Linux/macOS aggiungi -pthread. File e SVG usano la cartella di esecuzione; prima di sostituire un file viene chiesta conferma. Le scritture interrotte restano in una bozza nella destinazione.");
        internal static readonly FlowSourceTarget VisualBasic=new FlowSourceTarget("vbnet","Visual Basic .NET","vb","VisualBasicRuntime.txt","Salva Programma.vb. Con un compilatore Visual Basic .NET disponibile usa: vbc /r:System.Numerics.dll Programma.vb. Il file contiene il programma completo; file e disegni SVG usano la cartella di esecuzione.");
        internal static readonly FlowSourceTarget Groovy=new FlowSourceTarget("groovy","Groovy","groovy","JavaRuntime.txt","Salva Programma.groovy ed esegui con groovy Programma.groovy (Groovy 5+, Java 17+). Il file contiene il programma completo. File e bozze usano la cartella di esecuzione; i disegni si aprono in una finestra.");
        internal static readonly FlowSourceTarget Ruby=new FlowSourceTarget("ruby","Ruby","rb","RubyRuntime.rb","Salva Programma.rb ed esegui ruby Programma.rb (Ruby 3.3+). Non servono Frociart o gem aggiuntive. File e bozze usano la cartella di esecuzione; prima di sostituire un file viene chiesta conferma. Il disegno viene salvato in Frociart_disegno.svg. Su Windows il salvataggio usa Fiddle, incluso nelle installazioni complete di Ruby.");
        internal static readonly FlowSourceTarget PowerShell=new FlowSourceTarget("powershell","PowerShell","ps1","CSharpRuntime.txt","Salva Programma.ps1 in UTF-8 con BOM. Su Windows usa powershell -File Programma.ps1; con PowerShell 7+ usa pwsh -File Programma.ps1. Add-Type prepara il supporto .NET locale: la prima esecuzione può richiedere qualche secondo. Non servono Frociart o moduli esterni. File, bozze e disegni SVG usano la cartella di esecuzione.");
        internal static readonly FlowSourceTarget Php=new FlowSourceTarget("php","PHP","php","PhpRuntime.php","Salva Programma.php ed esegui php Programma.php sul computer (PHP 8.2+, CLI a 64 bit). Non servono Frociart o estensioni aggiuntive. File e bozze usano la cartella di esecuzione; prima di sostituire un file viene chiesta conferma. Il disegno viene salvato in Frociart_disegno.svg.");
        internal static readonly FlowSourceTarget[] All={Python,Java,Kotlin,CSharp,Cpp,JavaScript,TypeScript,VisualBasic,Groovy,Ruby,PowerShell,Php};
        internal readonly string Id,Name,Extension,Runtime,Instructions;
        internal readonly FlowCodeTemplate Template;internal readonly string TemplateId;
        private FlowSourceTarget(string id,string name,string extension,string runtime,string instructions,FlowCodeTemplate template=null,string templateId=null){Id=id;Name=name;Extension=extension;Runtime=runtime;Instructions=instructions;Template=template;TemplateId=templateId;}
        internal static FlowSourceTarget FromTemplate(string id,FlowCodeTemplate definition){if(definition==null)throw new ArgumentNullException("definition");if(id==null||!System.Text.RegularExpressions.Regex.IsMatch(id,"\\A[a-f0-9]{32}\\z"))throw new ArgumentException("Identificativo del modello non valido.");var basis=Find(definition.Base);string instructions=definition.Instructions.Length>0?definition.Instructions:basis==null?"Il formato è definito dal modello. Controlla il testo prima di usarlo nel programma di destinazione.":basis.Instructions;return new FlowSourceTarget("template:"+id,definition.Name,definition.Extension,basis==null?null:basis.Runtime,instructions,definition,id);}
        internal FlowSourceText Generate(FlowSource.Program program){try{if(Template!=null){var basis=Find(Template.Base);return Template.Generate(program,basis==null?null:basis.Generate(program));}if(this==Python)return FlowPython.Generate(program);if(this==Java)return FlowJava.Generate(program);if(this==Php)return FlowPhp.Generate(program);if(this==PowerShell)return FlowPowerShell.Generate(program);if(this==Ruby)return FlowRuby.Generate(program);if(this==Groovy)return FlowGroovy.Generate(program);if(this==Kotlin)return FlowKotlin.Generate(program);if(this==CSharp)return FlowCSharp.Generate(program);if(this==Cpp)return FlowCpp.Generate(program);if(this==VisualBasic)return FlowVisualBasic.Generate(program);if(this==JavaScript||this==TypeScript)return FlowJavaScript.Generate(program,this==TypeScript);throw new InvalidOperationException("Linguaggio non disponibile.");}catch(FlowException error){throw new ArgumentException(error.Message,error);}}
        internal FlowSourceText GenerateTyped(FlowSource.Program program,System.Collections.Generic.IDictionary<string,FlowDataType> choices){return Template!=null&&Template.Fpgt!=null?Template.GenerateTyped(program,null,choices):Generate(program);}
        internal string FileName(string source){if(Template!=null&&Template.Fpgt!=null&&Extension.Equals("java",StringComparison.OrdinalIgnoreCase)&&source!=null){var match=System.Text.RegularExpressions.Regex.Match(source,@"(?m)^[ \t]*public[ \t]+(?:(?:final|abstract)[ \t]+)?class[ \t]+([A-Za-z_$][A-Za-z0-9_$]{0,127})\b");if(match.Success&&!System.Text.RegularExpressions.Regex.IsMatch(match.Groups[1].Value,@"\A(?:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])\z",System.Text.RegularExpressions.RegexOptions.IgnoreCase))return match.Groups[1].Value+".java";}return "Programma."+Extension;}
        internal static FlowSourceTarget Find(string id){foreach(var target in All)if(target.Id==id)return target;return null;}
        internal static string NameOf(string id){var target=Find(id);return id=="pseudocode"?"Pseudocodice":id=="flowgorithm"?"Flowgorithm · .fpgt":target==null?id:target.Name;}
        internal static string SupportMarker(string id){return id=="vbnet"?"    ' --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---":id=="python"||id=="ruby"||id=="powershell"?SourceCodeDialog.SupportMarker:id=="java"||id=="kotlin"||id=="csharp"||id=="groovy"?"    // --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---":id=="cpp"||id=="javascript"||id=="typescript"||id=="php"?"// --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---":null;}
    }
}
